class Importer(
    private val io: CoroutineDispatcher,
    default: CoroutineDispatcher
) {
    private val parsers = default.limitedParallelism(2)

    suspend fun import(uri: Uri): Model {
        val bytes = withContext(io) {
            contentResolver.openInputStream(uri)?.use(::readBounded)
                ?: error("Cannot open $uri")
        }
        return withContext(parsers) { parse(bytes) }
    }

    private fun readBounded(input: InputStream): ByteArray {
        val output = ByteArrayOutputStream()
        val buffer = ByteArray(DEFAULT_BUFFER_SIZE)
        while (true) {
            val count = input.read(buffer)
            if (count < 0) return output.toByteArray()
            require(output.size() + count <= MAX_IMPORT_BYTES) { "Import is too large" }
            output.write(buffer, 0, count)
        }
    }
}

