suspend fun awaitLocation(): Location = suspendCancellableCoroutine { cont ->
    val completed = AtomicBoolean(false)
    lateinit var callback: LocationCallback

    fun complete(result: Result<Location>) {
        if (!completed.compareAndSet(false, true)) return
        client.removeLocationUpdates(callback)
        cont.resumeWith(result)
    }

    callback = object : LocationCallback() {
        override fun onLocationResult(result: LocationResult) {
            result.lastLocation?.let { complete(Result.success(it)) }
        }
    }

    try {
        client.requestLocationUpdates(request, callback, Looper.getMainLooper())
    } catch (error: Throwable) {
        complete(Result.failure(error))
        return@suspendCancellableCoroutine
    }
    cont.invokeOnCancellation {
        if (completed.compareAndSet(false, true)) client.removeLocationUpdates(callback)
    }
}

